package cn.paletale.companion;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import com.mojang.serialization.JsonOps;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;
import net.minecraft.world.item.*;
import net.minecraft.world.inventory.ClickType;
import net.minecraft.network.protocol.game.ServerboundContainerClosePacket;
/** Serial read-only menu traversal. Never clicks a land entry or any mutation control. */
public final class ChatChannelIcons {
 private record Cached(long day,JsonElement stack){}
 private static final Map<String,Cached> cache=new LinkedHashMap<>();private static final Map<String,ItemStack> decoded=new HashMap<>();private static final Set<String> attempted=new HashSet<>();private static final ArrayDeque<String> queue=new ArrayDeque<>();
 private static final java.util.concurrent.ExecutorService IO=java.util.concurrent.Executors.newSingleThreadExecutor(r->{var t=new Thread(r,"paletale-chat-icons");t.setDaemon(true);return t;});
 private static java.util.function.Consumer<Boolean> membershipCheck;private static long generation;private static int lastClosed=-1;private static long lastUntil;private static Screen lastScreen;private static Object lastConnection;private static Object connection;private static String account="",key;private static Screen previous;private static AbstractContainerScreen<?> hidden;private static int stage,id=-1,ticks;private static long start,day,sentAt;private static boolean contents,loaded;
 private static Path file(String a){return net.fabricmc.loader.api.FabricLoader.getInstance().getGameDir().resolve("paletale/chat-icons-v1/"+a+".json");}
 static void checkMembership(String peer,java.util.function.Consumer<Boolean> done){var c=Minecraft.getInstance();if(busy()||LandMenu.busy()||PlayerQuery.busy()||c.player==null||c.getConnection()!=connection||c.player.containerMenu!=c.player.inventoryMenu||!PrivateChat.scopeValid(peer.substring(3))){done.accept(false);return;}key=peer;previous=c.screen;membershipCheck=done;stage=0;sentAt=0;start=System.currentTimeMillis();ClientCommandQueue.background((peer.startsWith("国家:")?"n menu nation ":"l menu land ")+peer.substring(3),()->peer.equals(key)&&c.getConnection()==connection&&c.screen==previous,()->{start=System.currentTimeMillis();sentAt=start;});}
 static boolean message(String text){var c=Minecraft.getInstance();if(key==null||sentAt==0||c.getConnection()!=connection||System.currentTimeMillis()-sentAt>6000)return false;String value=clean(text);boolean denied=value.startsWith("领土")&&(value.contains("你不是国家")||value.contains("不受信任")||value.contains("不存在")||value.contains("没有这个名称"));if(!denied)return false;finish();return true;}
 static boolean busy(){return key!=null;}
 /** An icon seen while another reader had the territory menu open (the command wheel's second level shows them): kept in memory and in the daily disk cache. */
 static void learn(String peer,ItemStack stack){if(stack.isEmpty()||!peer.startsWith("领地:"))return;var known=decoded.get(peer);if(known!=null&&ItemStack.isSameItemSameComponents(known,stack))return;decoded.put(peer,stack.copyWithCount(1));remember(peer,stack);}
 static ItemStack icon(String peer){return decoded.getOrDefault(peer,new ItemStack(peer.startsWith("国家:")?Items.BEACON:Items.GRASS_BLOCK));}
 static void request(String peer){if((peer.startsWith("国家:")||peer.startsWith("领地:"))&&PrivateChat.scopeValid(peer.substring(3))&&queue.size()<64&&!queue.contains(peer)&&!attempted.contains(peer))queue.add(peer);}
 static void tick(){var c=Minecraft.getInstance();if(System.currentTimeMillis()>lastUntil||lastConnection!=c.getConnection()){lastClosed=-1;lastScreen=null;lastConnection=null;}String a=LedgerStore.account();long today=java.time.LocalDate.now(LedgerStore.BEIJING).toEpochDay();if(connection!=c.getConnection()||!account.equals(a)||day!=today){finish();long run=++generation;connection=c.getConnection();account=a;day=today;queue.clear();attempted.clear();decoded.clear();cache.clear();loaded=false;if(a.matches("[a-f0-9]{32}")){IO.execute(()->{JsonObject root=null;try{var f=file(a);if(Files.isRegularFile(f)&&Files.size(f)<2_000_000)root=JsonParser.parseString(Files.readString(f)).getAsJsonObject();}catch(Exception ignored){}var result=root;c.execute(()->{if(run!=generation||!account.equals(a)||connection!=c.getConnection())return;if(result!=null&&result.size()<=256)for(var entry:result.entrySet())try{var row=entry.getValue().getAsJsonObject();cache.put(entry.getKey(),new Cached(row.get("day").getAsLong(),row.get("stack")));}catch(Exception ignored){}loaded=true;});});}else loaded=true;}
  if(c.level==null||c.player==null||c.getConnection()==null)return;
  if(key==null){if(!loaded||!(c.screen instanceof PrivateChatScreen||c.screen instanceof NavigationHubScreen)||LandMenu.busy()||PlayerQuery.busy()||queue.isEmpty()||c.player.containerMenu!=c.player.inventoryMenu)return;String next=queue.removeFirst();attempted.add(next);var saved=cache.get(next);if(saved!=null){var restored=ItemStack.CODEC.parse(c.level.registryAccess().createSerializationContext(JsonOps.INSTANCE),saved.stack()).result().orElse(ItemStack.EMPTY);if(!restored.isEmpty())decoded.put(next,restored);if(saved.day()==today&&!restored.isEmpty())return;}if(c.getCurrentServer()==null||!ServerAccess.isSimmc(c.getCurrentServer().ip))return;key=next;previous=c.screen;stage=0;sentAt=0;start=System.currentTimeMillis();ClientCommandQueue.background(next.startsWith("国家:")?"n menu nation "+next.substring(3):"l",()->next.equals(key)&&c.getConnection()==connection&&c.screen==previous,()->{start=System.currentTimeMillis();sentAt=start;});return;}
  if(c.screen!=previous||System.currentTimeMillis()-start>6000){finish();return;}if(hidden==null||!contents||++ticks<2)return;int count=Math.max(0,hidden.getMenu().slots.size()-36);String title=clean(hidden.getTitle().getString());if(membershipCheck!=null){var callback=membershipCheck;membershipCheck=null;boolean valid=title.contains(key.substring(3));finish();callback.accept(valid);return;}
  if(key.startsWith("国家:")&&stage==0){if(!title.contains(key.substring(3))){finish();return;}for(int i=0;i<count;i++){var item=hidden.getMenu().slots.get(i).getItem();if(clean(item.getHoverName().getString()).equals("领土")){stage=1;contents=false;ticks=0;c.gameMode.handleInventoryMouseClick(id,i,0,ClickType.PICKUP,c.player);return;}}finish();return;}
  if(key.startsWith("国家:")){if(!title.contains("国家成员")&&!title.contains("领土")){finish();return;}for(int i=0;i<count;i++){var item=hidden.getMenu().slots.get(i).getItem();if(item.isEmpty())continue;String name=clean(item.getHoverName().getString());if(name.startsWith("首都")){remember(key,item);finish();return;}}}else if(title.contains("领土")||title.contains("领地")){for(int i=0;i<count;i++){var item=hidden.getMenu().slots.get(i).getItem();if(clean(item.getHoverName().getString()).equals(key.substring(3))){remember(key,item);finish();return;}}}finish();
 }
 private static String clean(String s){return s.replaceAll("§.","").strip();}
 private static void remember(String key,ItemStack stack){var c=Minecraft.getInstance();if(c.level==null)return;ItemStack.CODEC.encodeStart(c.level.registryAccess().createSerializationContext(JsonOps.INSTANCE),stack.copyWithCount(1)).result().ifPresent(json->{decoded.put(key,stack.copyWithCount(1));cache.put(key,new Cached(day,json));while(cache.size()>256){String first=cache.keySet().iterator().next();cache.remove(first);decoded.remove(first);}var root=new JsonObject();cache.forEach((k,v)->{var row=new JsonObject();row.addProperty("day",v.day());row.add("stack",v.stack());root.add(k,row);});String a=account,data=root.toString();IO.execute(()->{try{var f=file(a);Files.createDirectories(f.getParent());var temp=Files.createTempFile(f.getParent(),"icons-",".tmp");try{Files.writeString(temp,data);Files.move(temp,f,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(temp);}}catch(Exception ignored){}});});}
 public static boolean opening(Screen screen){var c=Minecraft.getInstance();if(key==null||c.screen!=previous||!(screen instanceof AbstractContainerScreen<?> menu)||c.player==null||c.player.containerMenu!=menu.getMenu())return false;String title=clean(menu.getTitle().getString());boolean expected=key.startsWith("领地:")?(title.contains("领土")||title.contains("领地")||membershipCheck!=null&&title.contains(key.substring(3))):stage==0?title.contains(key.substring(3)):(title.contains("国家成员")||title.contains("领土"));if(!expected){finish();return false;}hidden=menu;id=menu.getMenu().containerId;contents=false;ticks=0;return true;}
 public static void contents(int container){if(key!=null&&container==id)contents=true;}
 public static boolean closing(int container){if(key==null||container!=id){var c=Minecraft.getInstance();return container==lastClosed&&System.currentTimeMillis()<lastUntil&&c.getConnection()==lastConnection&&c.screen==lastScreen;}var c=Minecraft.getInstance();if(c.player!=null&&c.player.containerMenu.containerId==container)c.player.containerMenu=c.player.inventoryMenu;hidden=null;id=-1;return true;}
 private static void finish(){var c=Minecraft.getInstance();if(id>=0&&c.player!=null&&c.getConnection()==connection&&c.player.containerMenu.containerId==id){lastClosed=id;lastUntil=System.currentTimeMillis()+5000;lastScreen=previous;lastConnection=connection;c.getConnection().send(new ServerboundContainerClosePacket(id));c.player.containerMenu=c.player.inventoryMenu;}key=null;sentAt=0;hidden=null;id=-1;previous=null;var callback=membershipCheck;membershipCheck=null;if(callback!=null)callback.accept(false);}
}
